// Injects a real release signing config into the Gradle project generated by
// `expo prebuild`. The generated android/ folder is intentionally not committed
// (Continuous Native Generation), so signing is applied at build time instead.
const fs = require('fs');
const path = require('path');

const gradlePath = path.join(__dirname, '..', '..', 'android', 'app', 'build.gradle');

const base64 = process.env.ANDROID_KEYSTORE_BASE64;
const storePassword = process.env.ANDROID_KEYSTORE_PASSWORD;
const keyAlias = process.env.ANDROID_KEY_ALIAS;
const keyPassword = process.env.ANDROID_KEY_PASSWORD ?? storePassword;

function fail(message) {
  console.error(`::error::${message}`);
  process.exit(1);
}

if (!base64 || !storePassword || !keyAlias) {
  fail('Missing ANDROID_KEYSTORE_BASE64, ANDROID_KEYSTORE_PASSWORD or ANDROID_KEY_ALIAS.');
}

if (!fs.existsSync(gradlePath)) {
  fail(`Gradle project not found at ${gradlePath}. Run "npx expo prebuild" first.`);
}

const keystorePath = path.join(__dirname, '..', '..', 'android', 'app', 'release.keystore');
fs.writeFileSync(keystorePath, Buffer.from(base64, 'base64'));

const escaped = (value) => value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');

let source = fs.readFileSync(gradlePath, 'utf8');

// 1. Add a `release` signing config next to the generated `debug` one.
if (!source.includes('signingConfigs {')) {
  fail('Could not find the signingConfigs block in android/app/build.gradle.');
}

const releaseSigningBlock = `    release {
        storeFile file("${escaped(keystorePath.replace(/\\/g, '/'))}")
        storePassword "${escaped(storePassword)}"
        keyAlias "${escaped(keyAlias)}"
        keyPassword "${escaped(keyPassword)}"
    }
`;

if (!source.includes('signingConfigs.release')) {
  source = source.replace('signingConfigs {', `signingConfigs {\n${releaseSigningBlock}`);
}

// 2. Point the release build type at it (only inside buildTypes).
const buildTypesIndex = source.indexOf('buildTypes {');
if (buildTypesIndex === -1) {
  fail('Could not find the buildTypes block in android/app/build.gradle.');
}

const head = source.slice(0, buildTypesIndex);
let tail = source.slice(buildTypesIndex);
const releasePattern = /(release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;

if (releasePattern.test(tail)) {
  tail = tail.replace(releasePattern, '$1signingConfig signingConfigs.release');
} else if (/release\s*\{[\s\S]*?signingConfig signingConfigs\.release/.test(tail)) {
  // Already wired up.
} else {
  fail('Could not locate the release build type signingConfig line.');
}

source = head + tail;

if (!source.includes('signingConfig signingConfigs.release')) {
  fail('Signing config injection did not apply.');
}

fs.writeFileSync(gradlePath, source);
console.log('Release signing configured for android/app/build.gradle');
console.log(`Keystore: ${keystorePath}`);
console.log(`Alias: ${keyAlias}`);
